use std::fs;
use std::path::Path;

fn emit(p: &str, m: i32, t: i32) -> Result<(), i32> {
    let tpl = fs::read_to_string("/app/millrib/sheet.tpl").map_err(|_| 1)?;
    let out = tpl
        .replace("__P__", p)
        .replace("__M__", &m.to_string())
        .replace("__T__", &t.to_string());
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write("/app/bloturn/check.json", out).map_err(|_| 1)
}

fn rows(path: &Path) -> Result<i32, i32> {
    let text = fs::read_to_string(path).map_err(|_| 1)?;
    Ok(text.lines().filter(|line| !line.trim().is_empty()).count() as i32)
}

// Verify by reopening the live inputs.  In particular, never derive matched
// from ledger.json or from the staged copies.
fn live_count() -> Result<(i32, Vec<(i32, i32)>), i32> {
    let wall = fs::read_to_string("/app/opstext/WALL")
        .map_err(|_| 1)?
        .trim()
        .parse::<i32>()
        .map_err(|_| 1)?;
    let mut files = Vec::new();
    let rd = fs::read_dir("/app/daywell").map_err(|_| 1)?;
    for ent in rd {
        let ent = ent.map_err(|_| 1)?;
        let name = ent.file_name().to_string_lossy().into_owned();
        if name.len() != 13 || !name.starts_with('d') || !name.ends_with(".tbl") {
            continue;
        }
        let day = match name[1..9].parse::<i32>() {
            Ok(day) => day,
            Err(_) => continue,
        };
        if day <= wall {
            files.push((day, rows(&ent.path())?));
        }
    }
    if files.is_empty() {
        return Err(1);
    }
    files.sort_by_key(|item| item.0);
    let total = files.iter().map(|item| item.1).sum();
    Ok((total, files))
}

pub fn gait(taken: i32, packed: &[(i32, String)], floor_ok: bool) -> i32 {
    let _ = fs::remove_file("/app/bloturn/GUARD");
    let _ = fs::remove_file("/app/bloturn/check.json");
    let (matched, live) = match live_count() {
        Ok(value) => value,
        Err(_) => return 1,
    };
    if !floor_ok || matched != taken || packed.len() != live.len() {
        return 1;
    }
    // Confirm every live input, including the newest one, was restored with
    // the same row count under latest.
    for (day, expected) in &live {
        let path = format!("/app/packbay/latest/d{:08}.tbl", day);
        if rows(Path::new(&path)) != Ok(*expected) {
            return 1;
        }
    }
    if emit("/app/daywell", matched, taken).is_err() {
        return 1;
    }
    if fs::write("/app/bloturn/GUARD", "ok").is_err() {
        return 1;
    }
    0
}
